import java.io.*;

public class Main {
  public static void main(String[] args) throws IOException {
    ByteArrayOutputStream baos = new ByteArrayOutputStream();
    baos.write(300);
    ByteArrayInputStream bais = new ByteArrayInputStream(baos.toByteArray());
    int truncated = bais.read();
    System.out.println("write(300) read back: " + truncated);

    ByteArrayOutputStream numOut = new ByteArrayOutputStream();
    try (DataOutputStream dos = new DataOutputStream(numOut)) {
      dos.writeInt(0x12345678);
    }
    byte[] bytes = numOut.toByteArray();
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < bytes.length; i++) {
      if (i > 0) sb.append(" ");
      sb.append(String.format("%02X", bytes[i] & 0xFF));
    }
    System.out.println(sb.toString());
  }
}

