import java.io.*;
import java.nio.charset.StandardCharsets;

public class Main {
  public static void main(String[] args) throws IOException {
    byte[] rawInput = new byte[] {
      (byte) 0xEF, (byte) 0xBB, (byte) 0xBF,
      'n', 'a', 'm', 'e', ',', 'a', 'g', 'e', '\r', '\n',
      'A', 'd', 'a', ',', '3', '6', '\r', '\n'
    };

    ByteArrayOutputStream outBytes = new ByteArrayOutputStream();
    try (BufferedReader reader = new BufferedReader(
             new InputStreamReader(new ByteArrayInputStream(rawInput), StandardCharsets.UTF_8));
         BufferedWriter writer = new BufferedWriter(
             new OutputStreamWriter(outBytes, StandardCharsets.UTF_8))) {
      reader.mark(1);
      if (reader.read() != '\uFEFF') {
        reader.reset();
      }
      String line;
      while ((line = reader.readLine()) != null) {
        writer.write(line + "\n");
      }
    }

    String result = outBytes.toString(StandardCharsets.UTF_8);
    System.out.println("Starts with name: " + result.startsWith("name"));
    System.out.println("Output bytes: " + outBytes.size());
  }
}

